```js
const fmtPct = (p, dec = 2) => {
  if (p == null || !isFinite(p)) return "—";
  const r = Number(p.toFixed(dec));            // round first
  const sign = r > 0 ? "+" : r < 0 ? "−" : "";   // U+2212; use "-" if copy-to-spreadsheet matters
  return `${sign}${Math.abs(r).toFixed(dec)}%`;
};
const dirOf = p => (p == null ? 0 : Number(p.toFixed(2)) > 0 ? 1 : Number(p.toFixed(2)) < 0 ? -1 : 0);
```

