In backend.py, rename the current body to _get_market_news_fresh, fetch in parallel with a hard time budget, and cache it:

```python
from concurrent.futures import ThreadPoolExecutor, wait
_NEWS_TICKERS = ["^MXX", "^GSPC", "USDMXN=X", "GC=F", "CL=F", "BTC-USD"]
_NEWS_FEEDS = [ ...the same 9 URLs as today... ]

def _yf_news(t):
    try:
        return yft(t).news or []
    except Exception:
        return []

def _get_market_news_fresh() -> dict:
    seen, out = set(), []
    def add(p):
        if p.get("title") and p.get("url") and p["url"] not in seen:
            seen.add(p["url"])
            p["sentiment"] = classify_sentiment(p["title"] + " " + p["summary"])
            out.append(p)
    ex = ThreadPoolExecutor(max_workers=6)
    try:
        futs = [ex.submit(_yf_news, t) for t in _NEWS_TICKERS]
        done, _ = wait(futs, timeout=8)
        for f in futs:                      # keep priority order
            if f in done:
                for it in f.result()[:10]:
                    add(_extract_news_item(it))
        if len(out) < 5:
            futs = [ex.submit(_rss_news, u) for u in _NEWS_FEEDS]
            done, _ = wait(futs, timeout=7)
            for f in futs:
                if f in done:
                    for it in f.result():
                        add(it)
    finally:
        ex.shutdown(wait=False, cancel_futures=True)   # don't block on stragglers
    out.sort(key=lambda x: x.get("time", 0), reverse=True)
    return {"news": out[:30]}

def get_market_news() -> dict:
    return _cached("market_news", _get_market_news_fresh, ttl=300,
                   ok=lambda r: len(r.get("news", [])) >= 5)   # a weak or empty result is kept only fail_ttl=60 s
```

This caps the worst case at about 15 s instead of about 60 s. Concurrent users share one fetch every 5 minutes, and the existing _cached single-flight logic merges simultaneous requests.

